import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;

public class ImmutablePointTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Integer gx(ImmutablePoint p) {
        return p == null ? null : Integer.valueOf(p.getX());
    }

    static Integer gy(ImmutablePoint p) {
        return p == null ? null : Integer.valueOf(p.getY());
    }

    static String str(ImmutablePoint p) {
        return p == null ? null : p.toString();
    }

    public static void main(String[] args) {
        try {
            ImmutablePoint p = ImmutablePoint.of(3, 4);
            check("of(3, 4).getX()", 3, gx(p));
            check("of(3, 4).getY()", 4, gy(p));
            check("of(3, 4).toString()", "(3, 4)", str(p));

            ImmutablePoint q = p == null ? null : p.withX(9);
            check("p.withX(9).toString()", "(9, 4)", str(q));
            check("original p is unchanged", "(3, 4)", str(p));

            ImmutablePoint r = p == null ? null : p.withY(-2);
            check("p.withY(-2).toString()", "(3, -2)", str(r));

            int privateFinalFields = 0;
            for (Field f : ImmutablePoint.class.getDeclaredFields()) {
                if (f.isSynthetic()) {
                    continue;
                }
                if (Modifier.isPrivate(f.getModifiers()) && Modifier.isFinal(f.getModifiers())) {
                    privateFinalFields++;
                }
            }
            check("two private final fields", 2, privateFinalFields);

            boolean anySetter = false;
            for (Method m : ImmutablePoint.class.getDeclaredMethods()) {
                if (m.getName().startsWith("set")) {
                    anySetter = true;
                }
            }
            check("no setter methods exist", false, anySetter);
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

