public class ImmutablePoint {

    private final int x;
    private final int y;

    private ImmutablePoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public static ImmutablePoint of(int x, int y) {
        return new ImmutablePoint(x, y);
    }

    public int getX() {
        return x;
    }

    public int getY() {
        return y;
    }

    public ImmutablePoint withX(int newX) {
        return new ImmutablePoint(newX, y);
    }

    public ImmutablePoint withY(int newY) {
        return new ImmutablePoint(x, newY);
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}
